import React, { useState } from 'react';
import Data from '../Data.js';
import Card from '../components/Card.jsx';
import Navbar from '../components/Navbar.jsx';
import { IoSearchOutline } from 'react-icons/io5';
import { useLocation } from 'react-router-dom';

const Explore = () => {
    const location = useLocation();
    const queryParams = new URLSearchParams(location.search);
    const initialSearch = queryParams.get('q') || "";

    const [searchTerm, setSearchTerm] = useState(initialSearch);
    const [activeTab, setActiveTab] = useState("All");

    const categories = ["All", "Nature", "Culture", "Active", "Vibes", "History"];

    const filteredData = Data.filter(item => {
        const matchesSearch = item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
            item.location.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesTab = activeTab === "All" || item.category === activeTab;
        return matchesSearch && matchesTab;
    });

    return (
        <main className="explore-page">
            <Navbar defaultSticky />

            <div className="explore-header" style={{ background: 'var(--primary)', color: 'white', padding: '8rem 2rem 4rem', textAlign: 'center' }}>
                <h1>Explore Johannesburg</h1>
                <p>Discover the best nature trails, high-energy activities, and vibrant nightlife in the City of Gold.</p>

                <div className="explore-search-bar" style={{ display: 'flex', alignItems: 'center', background: 'white', borderRadius: '50px', padding: '0.5rem 1.5rem', maxWidth: '600px', margin: '2rem auto', color: 'var(--text-dark)' }}>
                    <IoSearchOutline />
                    <input
                        type="text"
                        placeholder="Search by city, country or title..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        style={{ border: 'none', outline: 'none', flex: 1, padding: '0.5rem', background: 'transparent' }}
                    />
                </div>

                <div className="explore-filters" style={{ display: 'flex', justifyContent: 'center', gap: '1rem', flexWrap: 'wrap', marginTop: '2rem' }}>
                    {categories.map(cat => (
                        <button
                            key={cat}
                            className={`category-tab ${activeTab === cat ? 'active' : ''}`}
                            onClick={() => setActiveTab(cat)}
                        >
                            {cat}
                        </button>
                    ))}
                </div>
            </div>

            <section className="content-grid">
                {filteredData.map(trip => (
                    <Card key={trip.id} {...trip} />
                ))}
            </section>

            {filteredData.length === 0 && (
                <div className="no-results">
                    <h3>No destinations match your search</h3>
                    <p>Try different keywords or browse all categories.</p>
                </div>
            )}
        </main>
    );
};

export default Explore;
