import React from 'react';
import { IoLocationOutline, IoStar, IoTimeOutline } from 'react-icons/io5';

export default function Card(props) {
    // Helper to render stars
    const renderStars = (rating) => {
        const stars = [];
        for (let i = 1; i <= 5; i++) {
            stars.push(
                <IoStar
                    key={i}
                    className={i <= Math.round(rating) ? "star-active" : "star-inactive"}
                    style={{ color: i <= Math.round(rating) ? "#d4a373" : "#e0e0e0" }}
                />
            );
        }
        return stars;
    };

    return (
        <article className="card">
            <div className="card-img-wrapper">
                <img loading="lazy" className="card-img" alt={props.title} src={props.img} />
                <span className="card-category">{props.category || "Travel"}</span>
            </div>

            <div className="card-content">
                <div className="card-rating">
                    {renderStars(props.rating || 4.5)}
                    <span className="rating-text">({props.rating || "4.5"})</span>
                </div>

                <h3 className="card-title">{props.title}</h3>

                <div className="location">
                    <IoLocationOutline />
                    <span>{props.location}</span>
                </div>

                <p className="description">
                    {props.description.length > 150
                        ? props.description.substring(0, 150) + "..."
                        : props.description}
                </p>

                <div className="card-footer">
                    <div className="card-meta">
                        <IoTimeOutline />
                        <span>{props.readTime || "5 min read"}</span>
                    </div>
                    <span className="card-date">{props.startDate.split(' ')[2]}</span>
                </div>
            </div>
        </article>
    );
}